from pathlib import Path
from docx import Document
from docx.shared import Pt, Inches, RGBColor

p = Path(__file__).resolve().parent
doc = Document()
styles = doc.styles
styles['Normal'].font.name = 'Times New Roman'
styles['Normal'].font.size = Pt(12)
for name in ['Title', 'Heading 1', 'Heading 2']:
    styles[name].font.name = 'Times New Roman'
    styles[name].font.color.rgb = RGBColor(0, 0, 0)
doc.add_heading('Понижение размерности пространства признаков', 0)
doc.add_paragraph('Лабораторная работа')
doc.add_heading('Цель работы', 1)
doc.add_paragraph('Исследовать методы понижения размерности из Scikit-learn, сравнить проекции и качество восстановления данных.')
doc.add_heading('Данные и подготовка', 1)
doc.add_paragraph('Использован набор Glass Identification: 214 образцов, 9 числовых признаков и 6 представленных классов. Идентификатор объекта исключён из признаков. Каждый признак масштабирован отдельно в диапазон от 0 до 1 методом MinMaxScaler. Метки классов используются только для окрашивания точек, а не при обучении методов. Источник: B. German, Glass Identification, UCI Machine Learning Repository, 1987, https://doi.org/10.24432/C5WW2P. В задании указан Kaggle; здесь использован исходный набор UCI.')
doc.add_paragraph('На диаграммах классам 1, 2, 3, 5, 6 и 7 соответствуют синий, оранжевый, зелёный, красный, фиолетовый и коричневый цвета. Класс 4 в наборе отсутствует.')
doc.add_picture(str(p/'pairs.png'), width=Inches(6.7))
doc.add_heading('Результаты работы программы', 1)
doc.add_paragraph((p/'results.txt').read_text(encoding='utf-8').strip(), style='Normal')
doc.add_picture(str(p/'methods.png'), width=Inches(6.7))
doc.add_heading('Анализ результатов', 1)
doc.add_paragraph('Первые две главные компоненты объясняют 45,43% и 17,99% общей дисперсии, вместе 63,42%. Соответствующие собственные числа ковариационной матрицы равны 0,122349 и 0,048450. Следовательно, на двумерной проекции теряется 36,58% дисперсии. Три компоненты дают 76,07%, а четыре — 85,87%; поэтому минимальное число компонент для порога 85% равно четырём.')
doc.add_paragraph('Метод inverse_transform восстанавливает нормированные признаки по двум координатам с MSE 0,010895. Это средний квадрат разности по всем объектам и признакам; восстановление не может быть точным, поскольку отброшенные компоненты содержат часть информации. Все исследованные варианты svd_solver дали 63,4197%: для этой небольшой матрицы они находят практически одно и то же двумерное подпространство. Randomized — приближённый алгоритм, поэтому для воспроизводимости задан random_state.')
doc.add_paragraph('Линейный KernelPCA эквивалентен обычному PCA после центрирования: попарные расстояния проекций совпадают с точностью вывода; знаки и ориентация осей могут отличаться. RBF-ядро создаёт нелинейную проекцию, а параметр gamma меняет масштаб сходства. Для gamma 0,5 и 5 MSE приближённого обратного преобразования составляет 0,010943 и 0,011644 соответственно. Для линейного ядра функция inverse_transform в данной реализации обучает отдельную регуляризованную модель обратного отображения без свободного члена, поэтому её MSE 0,137199 не означает, что прямая проекция отличается от PCA. MSE KernelPCA зависит от способа приближённого восстановления и не является долей объяснённой дисперсии.')
doc.add_paragraph('SparsePCA формирует разреженные нагрузки: при alpha=0,1 нулевых нагрузок 3 из 18 и MSE 0,010934; при alpha=1 — 14 из 18 и MSE 0,013890. Усиление разреженности упрощает описание компонент, но здесь ухудшает восстановление. Для восстановления использовано произведение координат на матрицу компонент с добавлением среднего. Доли дисперсии обычного PCA нельзя напрямую переносить на неортогональные компоненты SparsePCA.')
doc.add_paragraph('FactorAnalysis с двумя факторами даёт MSE 0,011539 на той же нормированной выборке. PCA ищет направления максимальной общей дисперсии; факторный анализ описывает наблюдения через общие скрытые факторы и отдельные дисперсии шума признаков. Поэтому направления и координаты методов различаются. На графиках классы частично перекрываются: методы не используют метки классов и не оптимизируют их разделение. Ошибки восстановления рассчитаны на обучающих данных и не являются оценкой качества на новых наблюдениях.')
doc.add_heading('Код программы', 1)
for line in (p/'main.py').read_text(encoding='utf-8-sig').splitlines():
    para = doc.add_paragraph()
    para.paragraph_format.space_after = Pt(0)
    para.paragraph_format.line_spacing = 1
    run = para.add_run(line or ' ')
    run.font.name = 'Consolas'
    run.font.size = Pt(8)
doc.save(p/'Отчёт.docx')
